body_md:
The space of entire functions with exponential growth is defined as
\begin{equation}\label{Eq_A1}
\mathcal{A}_1(\mathbb{C})\coloneqq\Set{F:\mathbb{C}\rightarrow\mathbb{C}\text{ entire} | \exists A,B\geq 0\text{ such that }|F(z)|\leq Ae^{B|z|}\text{ for all }z\in\mathbb{C}}.
\end{equation}
For any $F_0,(F_n)_n\in\mathcal{A}_1(\mathbb{C})$ we say that $F_n\rightarrow F_0$ converges in $\mathcal{A}_1(\mathbb{C})$ if and only if there exists some $B\geq 0$, such that
\begin{equation}\label{Eq_A1_convergence}
\lim\limits_{n\rightarrow\infty}\sup\limits_{z\in\mathbb{C}}|F_n(z)-F_0(z)|e^{-B|z|}=0.
\end{equation}

\label{defi_Superoscillation}
A sequence of functions of the form
\begin{equation}\label{Eq_Superoscillating_integral}
F_n(z)=\int_{-k_0}^{k_0}e^{ikz}d\mu_n(k),\quad z\in\mathbb{C},
\end{equation}
with a common maximal frequency $k_0>0$ and complex Borel measures $\mu_n$ on $[-k_0,k_0]$, is called superoscillating, if there exists some $a\in\mathbb{R}\setminus[-k_0,k_0]$, such that
\begin{equation}\label{Eq_Superoscillating_convergence}
\lim\limits_{n\rightarrow\infty}F_n(z)=e^{iaz}\quad\text{in }\mathcal{A}_1(\mathbb{C}).
\end{equation}

\label{satz_Fdelta}
For $b\geq a>0$ let $\Delta\subseteq\mathbb{C}$ be the open triangle with corners $ia$ and $\pm b$. Consider measurable functions $k,g:\mathbb{R}\cup\overline{\Delta}\rightarrow\mathbb{C}$ which for some $B\geq 0$ satisfy the bounds
\begin{equation}\label{Eq_Fdelta_assumptions}
\sup\limits_{u\in\mathbb{R}}|k(u)|<\infty\quad\text{and}\quad\sup\limits_{u\in\mathbb{R}}|g(u)|e^{-B|u|}<\infty.
\end{equation}
Moreover, assume that $k$ and $g$ are continuous on $\overline{\Delta}$, holomorphic on $\Delta$, and in the case $a=b$ their derivatives are bounded on $\Delta$. Then, for every $\delta>0$, the functions
\begin{equation}\label{Eq_Fdelta}
F_\delta(z)\coloneqq\frac{1}{\delta\sqrt{2\pi}}\int_\mathbb{R}g(u)e^{ik(u)z}e^{-\frac{(u-ia)^2}{2\delta^2}}du,\quad z\in\mathbb{C},
\end{equation}
belong to the space $\mathcal{A}_1(\mathbb{C})$ and converge as
\begin{equation}\label{Eq_Fdelta_convergence}
\lim\limits_{\delta\rightarrow 0^+}F_\delta(z)=g(ia)e^{ik(ia)z}\quad\text{in }\mathcal{A}_1(\mathbb{C}).
\end{equation}

We shall make use of the constants
\begin{equation*}
C\coloneqq\sup\limits_{u\in\mathbb{R}}|k(u)|\quad\text{and}\quad A\coloneqq\sup\limits_{u\in\mathbb{R}}|g(u)|e^{-B|u|},
\end{equation*}
which are finite due to assumption \eqref{Eq_Fdelta_assumptions}. A straightforward estimate shows
\begin{equation}\label{esti1}
|F_\delta(z)|\leq\frac{1}{\delta\sqrt{2\pi}}\int_\mathbb{R}|g(u)|e^{|k(u)||z|}e^{\frac{-u^2+a^2}{2\delta^2}}du\leq\frac{A}{\delta\sqrt{2\pi}}e^{\frac{a^2}{2\delta^2}} \bigg(\int_\mathbb{R}e^{B|u|}e^{-\frac{u^2}{2\delta^2}}du \bigg)e^{C|z|}, 
\end{equation}
and hence $F_\delta$ is well defined for every $\delta>0$. Furthermore, a version of the dominated convergence 
theorem shows that $F_\delta$ is holomorphic and together with the above estimate it follows that $F_\delta$, 
$\delta>0$,
belongs to the space $\mathcal{A}_1(\mathbb{C})$.

\medskip

In the following we will verify that $F_\delta$ converges as in \eqref{Eq_Fdelta_convergence}. First, we change the part $-b\rightarrow b$ of the integration path in \eqref{Eq_Fdelta} to $-b\rightarrow ia\rightarrow b$, that is, we use
\begin{equation*}
\int_{-b}^bg(u)e^{ik(u)z}e^{-\frac{(u-ia)^2}{2\delta^2}}du=\int_{-b}^{ia}g(u)e^{ik(u)z}e^{-\frac{(u-ia)^2}{2\delta^2}}du+\int_{ia}^bg(u)e^{ik(u)z}e^{-\frac{(u-ia)^2}{2\delta^2}}du.
\end{equation*}
In fact,
since $g$ and $k$ are holomorphic on $\Delta$ and continuous on $\overline{\Delta}$ the above equality follows 
from the Cauchy theorem applied to the boundary of the scaled triangle $\Delta_\varepsilon$ and then taking the limit $\varepsilon\rightarrow 0^+$.
\begin{center}
\begin{tikzpicture}[scale=1.4]
\draw[->] (-1.2,0)--(1.3,0);
\draw (1.2,0) node[anchor=south] {\tiny{$\operatorname{Re}$}};
\draw[->] (0,-0.2)--(0,1.2) node[anchor=west] {\tiny{$\operatorname{Im}$}};
\draw (-1,0)--(0,1)--(1,0);
\draw[ultra thick] (-0.76,0.1)--(0,0.86)--(0.76,0.1)--(-0.76,0.1);
\draw[ultra thick,->] (-0.76,0.1)--(-0.16,0.7);
\draw[ultra thick,->] (0,0.86)--(0.65,0.21);
\draw[ultra thick,->] (-0.76,0.1)--(0.4,0.1);
\draw[fill=white] (-1,0) circle (0.05) node[anchor=north] {\small{-$b$}};
\draw[fill=white] (1,0) circle (0.05) node[anchor=north] {\small{$b$}};
\draw[fill=white] (0,1) circle (0.05) node[anchor=west] {\small{$ia$}};
\draw[>-<] (0,-0.05)--(0,0.165);
\draw (-0.05,0.05) node[anchor=north west] {\tiny{$\varepsilon$}};
\draw[>-<] (-0.535,0.535)--(-0.384,0.384);
\draw (-0.55,0.55)--(-0.38,0.38);
\draw (-0.5,0.5) node[anchor=south] {\tiny{$\varepsilon$}};
\draw[>-<] (0.535,0.535)--(0.384,0.384);
\draw (0.55,0.55)--(0.38,0.38);
\draw (0.5,0.5) node[anchor=south] {\tiny{$\varepsilon$}};
\draw[fill=white] (-0.76,0.1) circle (0.05);
\draw[fill=white] (0.76,0.1) circle (0.05);
